 "content": "from collections import deque


def transform(grid):
    """Fill each hollow rectangular frame with the color whose loose-dot
    count matches the frame's checkerboard capacity, then remove loose dots.
    """
    h, w = len(grid), len(grid[0])
    seen = set()
    frames = []

    # Find monochrome 4-connected components that form rectangular outlines.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0 = min(y for y, _ in cells)
            r1 = max(y for y, _ in cells)
            c0 = min(x for _, x in cells)
            c1 = max(x for _, x in cells)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            border = {(y, x) for y in range(r0, r1 + 1) for x in range(c0, c1 + 1)
                      if y in (r0, r1) or x in (c0, c1)}
            if set(cells) == border:
                frames.append((color, r0, r1, c0, c1))

    frame_cells = { (r, c) for _, r0, r1, c0, c1 in frames
                    for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
                    if r in (r0, r1) or c in (c0, c1) }
    counts = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color and (r, c) not in frame_cells:
                counts[color] = counts.get(color, 0) + 1

    out = [[0] * w for _ in range(h)]
    for color, r0, r1, c0, c1 in frames:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if r in (r0, r1) or c in (c0, c1):
                    out[r][c] = color
        ih, iw = r1 - r0 - 1, c1 - c0 - 1
        capacity = (ih * iw + 1) // 2
        fill = next((k for k, n in counts.items() if n == capacity), None)
        if fill is not None:
            for r in range(r0 + 1, r1):
                for c in range(c0 + 1, c1):
                    if (r - r0 - 1 + c - c0 - 1) % 2 == 0:
                        out[r][c] = fill
    return out


